function Mark({ p }: { p: Platform }) {
    if (p.path) {
        return (
            <svg viewBox="0 0 24 24" width="30" height="30" fill={p.color} aria-hidden="true" focusable="false">
                <path d={p.path} />
            </svg>
        );
    }
    return (
        <span className="platforms-mono" style={{ background: p.color }} aria-hidden="true">
            {p.mono}
        </span>
    );
}

const total = GROUPS.reduce((n, g) => n + g.items.length, 0);

type PlatformsProps = { eyebrow?: string; titleLead?: string; titleAccent?: string; subtitle?: React.ReactNode };

export default function Platforms({
    eyebrow = "Platforms We Support",
    titleLead = "Built for the Platforms",
    titleAccent = "You Already Use",
    subtitle,
}: PlatformsProps = {}) {
    return (
        <section className="platforms" aria-labelledby="platforms-title">
            <div className="container">
                <header className="platforms-header">
                    <p className="platforms-eyebrow">{eyebrow}</p>
                    <h2 id="platforms-title" className="platforms-title">
                        {titleLead} <span>{titleAccent}</span>
                    </h2>
                    <p className="platforms-subtitle">
                        {subtitle ?? (<>
                        Every HTML email template is coded for your ESP and tested across major email clients, so it works in{" "}
                        <strong>Klaviyo, Mailchimp, HubSpot</strong> and {total - 3}+ other platforms from day one.
                        </>)}
                    </p>
                </header>

                <div className="platforms-groups">
                    {GROUPS.map((group) => (
                        <div key={group.id} className={`platforms-group platforms-group--${group.id}`}>
                            <h3 className="platforms-group-title">{group.label}</h3>
                            <ul className="platforms-grid">
                                {group.items.map((p) => (
                                    <li key={p.name} className="platforms-item" style={{ "--brand": p.color } as React.CSSProperties}>
                                        <Mark p={p} />
                                        <span className="platforms-name">{p.name}</span>
                                    </li>
                                ))}
                            </ul>
                        </div>
                    ))}
                </div>
            </div>
        </section>
    );
}
